seeds=[(2,10,4),(14,16,8),(21,27,6)]
inside=[]
for i in range(1,29):
 for j in range(1,29):
  if R[i][j]==1 and all(R[x][y]==1 for x in range(i-1,i+2) for y in range(j-1,j+2)):
   inside.append((i,j))
from collections import Counter
Counter(min(seeds,key=lambda s:(i-s[0])**2+(j-s[1])**2)[2] for i,j in inside), len(inside),inside

from collections import deque
H=W=30
seen=set(); comps=[]
for i in range(H):
 for j in range(W):
  if R[i][j] and (i,j) not in seen:
   q=[(i,j)];seen.add((i,j)); cells=[]
   for x,y in q:
    cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=x+dx,y+dy
     if 0<=p[0]<H and 0<=p[1]<W and R[p[0]][p[1]] and p not in seen:
      seen.add(p);q.append(p)
   comps.append(cells)
for k,c in enumerate(comps):
 ms=[(i,j,R[i][j]) for i,j in c if R[i][j]>1]
 elig=[p for p in inside if p in set(c)]
 if ms or elig: print(k,len(c), (min(i for i,j in c),max(i for i,j in c),min(j for i,j in c),max(j for i,j in c)),ms,len(elig))

qual=[]
for i in range(1,29):
 for j in range(1,29):
  if R[i][j]==1 and all(R[x][y]!=0 for x in range(i-1,i+2) for y in range(j-1,j+2)):
   qual.append((i,j))
Counter(next(R[x][y] for x,y in c if R[x][y]>1) for c in comps for p in qual if p in c),len(qual)

out=[row[:] for row in R]
comp_of={p:k for k,c in enumerate(comps) for p in c}
color_by_comp={k: next(R[i][j] for i,j in c if R[i][j]>1) for k,c in enumerate(comps) if any(R[i][j]>1 for i,j in c)}
for i,j in qual:
 k=comp_of[(i,j)]
 if k in color_by_comp: out[i][j]=color_by_comp[k]
print('\n'.join(' '.join(map(str,row)) for row in out))
# summary colored coords by color
for col in [4,8,6]: print(col,[(i,j) for i,row in enumerate(out) for j,v in enumerate(row) if v==col])
